def modal_kinds(text_n):
    return {k for k, r in MODAL_RES.items() if r.search(text_n)}


def qualifiers(text_n):
    out = set()
    for k, r in QUALIFIER_RES.items():
        for m in r.finditer(text_n):
            out.add((k, m.group(0)))
    return out


# Condicional verbal sobre el texto CON tildes (F1): «podría», «aumentaría»,
# «superarían». Con tildes se descartan «convocatoria», «memoria», «primaria»;
# los sustantivos en «-ería» (consejería, quesería) se excluyen salvo verbos -er.
COND_RE = re.compile(r"\b(\w+?)(aría|iría|dría|ría)(n?)\b")
COND_ER = re.compile(r"\b(?:ser|deber|ver|crecer|parecer|ofrecer|aparecer|mantener|poder|comer|caber|haber|saber|hacer|decir|querer)ía|\b\w+cería\b")
COND_IRREG = {"podría", "haría", "diría", "querría", "habría", "sabría", "cabría", "valdría", "tendría",
              "pondría", "saldría", "vendría", "obtendría", "mantendría", "contendría", "convendría"}


def has_conditional(raw):
    t = raw.lower()
    for m in re.finditer(r"\b\w+ían?\b", t):
        w = m.group(0)
        base = w[:-1] if w.endswith("n") else w
        if base in COND_IRREG or base.endswith(("aría", "iría", "dría")):
            return True
        if base.endswith("ería") and (COND_ER.search(base) or base in ("sería", "debería", "vería")):
            return True
    return False


def qual_kinds(text_n, raw=None):
    out = {k for k, r in QUALIFIER_RES.items() if k != "condicional" and r.search(text_n)}
    if raw is not None:
        if has_conditional(raw):
            out.add("condicional")
    elif QUALIFIER_RES["condicional"].search(text_n):
        out.add("condicional")
    return out


def local_window(ans_stems, src_raw, pad=4):
    """Trozo de la fuente que la respuesta parafrasea (de la primera a la última
    palabra compartida, con margen). Los matices se buscan solo ahí: un «podría»
    en otra cláusula de la fuente no es un matiz perdido de ESTA afirmación."""
    words = re.findall(r"\S+", src_raw)
    idx = [i for i, w in enumerate(words)
           if (lambda n: n not in STOP and len(n) > 2 and stem(n) in ans_stems)(norm(re.sub(r"\W", "", w)))]
    if not idx:
        return src_raw
    lo, hi = max(0, idx[0] - pad), min(len(words), idx[-1] + pad + 1)
    return " ".join(words[lo:hi])


CAPS_RE = re.compile(r"\b([A-ZÁÉÍÓÚÑ][a-záéíóúüñ]+(?:[- ][A-ZÁÉÍÓÚÑ][a-záéíóúüñ]+)*)")


def caps(text):
    out = set()
    for m in CAPS_RE.finditer(text):
        start = m.start()
        # descarta la palabra inicial de oración si es una palabra común
        prev = text[:start].rstrip()
        token = norm(m.group(1))
        if (not prev or prev[-1] in ".:;!?¿¡«\"(") and token.split()[0] in STOP:
            continue
        for part in re.split(r"[- ]", token):
            if part not in STOP and len(part) > 2:
                out.add(part)
    return out


def count_phrases(text_n, phrases):
    return {p for p in phrases if p in text_n}


# --------------------------------------------------------------------------- features


def _mx(xs, d=0.0):
    return max(xs) if xs else d


def sentence_features(oracion, frags, caso, src_ctx):
    fuentes = caso["fuentes"]
    n_src = max(1, len(fuentes))
    rp = oracion.get("respaldo_por_fuente") or [0.0]
    cp = oracion.get("contradiccion_por_fuente") or [0.0]
    sp = oracion.get("similitud_por_fuente") or [0.0]
    rt = oracion.get("respaldo_todas", 0.0) or 0.0
    ct = oracion.get("contradiccion_todas", 0.0) or 0.0
    llm = oracion.get("llm") or {}
    ver = llm.get("veredicto")
    conf = llm.get("confianza")
    conf = 0.5 if conf is None else float(conf)
    fi = llm.get("fuente")
    if not isinstance(fi, int) or not (0 <= fi < len(fuentes)):
        fi = None

    f = {}
    f["llm_resp"] = 1.0 if ver == "respaldada" else 0.0
    f["llm_nores"] = 1.0 if ver == "no_respaldada" else 0.0
    f["llm_contra"] = 1.0 if ver == "contradicha" else 0.0
    f["llm_null"] = 1.0 if ver is None else 0.0
    f["llm_conf"] = conf
    f["llm_bad"] = (conf if ver in ("no_respaldada", "contradicha") else
                    (1 - conf) if ver == "respaldada" else 0.5)
    f["rt"] = rt
    f["ct"] = ct
    f["max_r"] = _mx(rp)
    f["max_c"] = _mx(cp)
    f["max_s"] = _mx(sp)
    f["sup"] = max(rt, _mx(rp))
    # fuente que más se parece (o la que cita el LLM)
    best = fi if fi is not None else max(range(len(sp)), key=lambda i: sp[i]) if sp else None
    if best is not None and best < len(rp):
        f["cit_r"] = rp[best]
        f["cit_c"] = cp[best] if best < len(cp) else 0.0
        f["cit_s"] = sp[best] if best < len(sp) else 0.0
    else:
        f["cit_r"] = f["cit_c"] = f["cit_s"] = 0.0
    f["cit_none"] = 1.0 if fi is None else 0.0

    # fragmentos: el fragmento peor respaldado manda
    fr_sup, fr_con, fr_bad = [], [], []
    for fr in frags:
        frp = fr.get("respaldo_por_fuente") or [0.0]
        fcp = fr.get("contradiccion_por_fuente") or [0.0]
        s = max(fr.get("respaldo_todas", 0.0) or 0.0, _mx(frp))
        c = max(fr.get("contradiccion_todas", 0.0) or 0.0, 0.0)
        fr_sup.append(s)
        fr_con.append(c)
        fr_bad.append((1 - s) * max(c, _mx(fcp)))
    f["fr_min_sup"] = min(fr_sup) if fr_sup else f["sup"]
    f["fr_max_con"] = _mx(fr_con, ct)
    f["fr_max_bad"] = _mx(fr_bad)
    f["n_frag"] = float(len(frags))

    # --- comprobaciones propias -------------------------------------------
    texto = oracion.get("texto") or ""
    tn = norm(texto)
    nums = [v for v in extract_numbers(texto) if not is_trivial(v)]
    src_nums = src_ctx["nums"]
    q_nums = src_ctx["q_nums"]
    direct_unk = [v for v in nums if not num_match(v, src_nums | q_nums)]
    arith_unk = [v for v in direct_unk if not num_match(v, src_ctx["derived"])]
    f["n_nums"] = float(len(nums))
    f["num_unk"] = float(len(direct_unk))
    f["num_unk_arith"] = float(len(arith_unk))
    f["num_derived"] = float(len(direct_unk) - len(arith_unk))
    # cuenta «ajustada»: la cifra nueva debe salir de una cuenta con otra cifra
    # de la propia oración (si no, es una cifra inventada o una cuenta mal hecha)
    times = extract_times(texto) + src_ctx["times"]
    tight_unk = []
    for k, v in enumerate(direct_unk):
        others = [u for u in nums if u != v and u > 0]
        pool = tight_derived(others, src_nums, times) | tight_derived(others, others, ())
        if not num_match(v, pool):
            tight_unk.append(v)
    f["num_unk_tight"] = float(len(tight_unk))

    # coherencia aritmética DENTRO de la oración. Si la oración trae sus propios
    # operandos (cifras que sí están en las fuentes) y además una cifra nueva,
    # esa cifra nueva debe salir de las cuentas con ESOS operandos. Si solo sale
    # «por casualidad» de otras cifras de las fuentes, la cuenta está mal hecha.
    core = [v for v in nums if v > 0 and not is_year(v)]
    # operandos: cifras de la oración que están en las fuentes (sin contar
    # enteros pequeños tipo «seis meses», «tres nacionalidades»)
    operands = [v for v in core if num_match(v, src_nums) and not (v <= 12 and float(v).is_integer())]
    t_ans = extract_times(texto)
    a_ok = b_ok = loose_only = bad_ops = none_ok = 0
    for v in core:
        if v in operands or num_match(v, q_nums):
            continue
        others = [u for u in core if u != v]
        if num_match(v, internal_derived(others, t_ans + src_ctx["times"])):
            a_ok += 1
        elif num_match(v, limited_cross(others, src_nums)):
            b_ok += 1
        elif num_match(v, src_ctx["derived"]):
            loose_only += 1
            if operands:
                bad_ops += 1
        else:
            none_ok += 1
            if operands:
                bad_ops += 1
    f["ar_internal"] = float(a_ok)
    f["ar_cross"] = float(b_ok)
    f["ar_loose_only"] = float(loose_only)
    f["ar_none"] = float(none_ok)
    f["ar_bad_ops"] = float(bad_ops)
    # porcentajes: un «18 %» tiene que ser un porcentaje de las fuentes o salir
    # de las cuentas con las cifras de la oración
    pcts = extract_pcts(texto)
    src_pcts = src_ctx["pcts"] | {100 - x for x in src_ctx["pcts"]}
    aprox = re.search(r"\b(mas de|mas del|menos de|menos del|casi|cerca de|alrededor de|en torno a|algo mas de|algo menos de|unos|unas)\b", tn)
    pct_bad = 0
    for v in pcts:
        if num_match(v, src_pcts):
            continue
        others = [u for u in core if not close(u, v)]
        if (num_match(v, internal_derived(others)) or num_match(v, limited_cross(others, src_nums))
                or (aprox and num_match(v, src_ctx["derived"]))):
            continue
        if aprox:
            w = aprox.group(1)
            lo, hi = (v - 12, v) if w.startswith("menos") or w == "casi" else (
                (v, v + 12) if w.startswith("mas") or w.startswith("algo mas") else (v - 4, v + 4))
            local = internal_derived(others) + limited_cross(others, src_nums) + sorted(src_pcts)
            if any(lo <= c <= hi for c in local):
                continue
        pct_bad += 1
    f["pct_bad"] = float(pct_bad)
    f["n_pcts"] = float(len(pcts))
    # todas las cifras comprobadas (directas o con cuentas coherentes): explica
    # por qué el NLI no respalda una frase fiel que hace cuentas (F6/F7)
    f["nums_verified"] = 1.0 if (core and none_ok == 0 and bad_ops == 0 and pct_bad == 0) else 0.0
    f["num_ok_tight"] = float(len(direct_unk) - len(tight_unk))

    # atribución: la cifra sale de una fuente que habla de OTRA entidad
    ans_caps = caps(texto) | src_ctx["q_caps"]
    foreign = 0
    for v in nums:
        holders = [i for i, ns in enumerate(src_ctx["src_nums"]) if num_match(v, ns)]
        if not holders:
            continue
        ok = False
        for i in holders:
            extra = src_ctx["src_caps"][i] - ans_caps - src_ctx["common_caps"]
            if not extra:
                ok = True
                break
        if not ok:
            foreign += 1
    f["num_foreign"] = float(foreign)

    # palabras de contenido nuevas (ni en fuentes ni en la pregunta)
    stems = content_stems(texto)
    novel = stems - src_ctx["all_stems"] - src_ctx["q_stems"]
    f["novel"] = float(len(novel))
    f["novel_ratio"] = len(novel) / max(1, len(stems))
    if best is not None:
        cs = src_ctx["src_stems"][best]
        nov_cit = stems - cs - src_ctx["q_stems"]
        f["novel_cit_ratio"] = len(nov_cit) / max(1, len(stems))
    else:
        f["novel_cit_ratio"] = f["novel_ratio"]

    # fuentes relevantes para la oración: la citada + las muy parecidas
    rel = set()
    if best is not None:
        rel.add(best)
    for i, s in enumerate(sp):
        if s >= 0.6 or (rp[i] if i < len(rp) else 0) >= 0.5:
            rel.add(i)
    rel_text = " ".join(src_ctx["src_norm"][i] for i in rel if i < len(fuentes))
    all_text = src_ctx["all_norm"]

    # fuentes ancla: la citada + las que contienen las cifras de la oración
    anchors = set([best]) if best is not None else set()
    for v in nums:
        for i, ns in enumerate(src_ctx["src_nums"]):
            if num_match(v, ns):
                anchors.add(i)
    for i in range(len(rp)):
        if rp[i] >= 0.5 and i < len(fuentes):
            anchors.add(i)
    anc_text = " ".join(src_ctx["src_norm"][i] for i in anchors if i < len(fuentes))
    cit_text = src_ctx["src_norm"][best] if best is not None and best < len(fuentes) else ""
    q_ans = qual_kinds(tn, texto)
    cit_raw = fuentes[best] if best is not None and best < len(fuentes) else ""
    anc_raw = " ".join(fuentes[i] for i in anchors if i < len(fuentes))
    q_cit = qual_kinds(cit_text, cit_raw)
    q_anc = qual_kinds(anc_text, anc_raw)
    win = local_window(stems, cit_raw) if cit_raw else ""
    q_loc = qual_kinds(norm(win), win)
    f["qual_lost_local"] = float(len(q_loc - q_ans))
    # F2: futuro afirmado en la respuesta cuando el tramo de la fuente no lo usa
    fut = re.compile(r"\b\w{3,}(?:rá|rán)\b")
    f["fut_new"] = 1.0 if (fut.search(texto.lower()) and not fut.search(win.lower())) else 0.0
    m_ans, m_anc = modal_kinds(tn), modal_kinds(anc_text)
    f["modal_new"] = float(len((m_ans - m_anc) - {"negacion"}))
    f["modal_lost"] = float(len((m_anc - m_ans) - {"negacion"}))
    f["neg_flip"] = 1.0 if (("negacion" in m_ans) != ("negacion" in modal_kinds(cit_text))) else 0.0
    f["qual_lost_cit"] = float(len(q_cit - q_ans))
    f["qual_lost_anc"] = float(len(q_anc - q_ans))
    f["qual_new"] = float(len(q_ans - q_anc))
    for k in QUALIFIER_RES:
        f["ql_" + k] = 1.0 if (k in q_cit and k not in q_ans) else 0.0
    nums_cit = src_ctx["src_nums"][best] if best is not None and best < len(fuentes) else set()
    f["num_not_cit"] = float(sum(1 for v in nums if not num_match(v, nums_cit)))
    f["n_anchor"] = float(len(anchors))
    stems_anc = set().union(*[src_ctx["src_stems"][i] for i in anchors if i < len(fuentes)]) if anchors else set()
    f["novel_anc_ratio"] = len(stems - stems_anc - src_ctx["q_stems"]) / max(1, len(stems))
    f["causal_new_anc"] = float(len(count_phrases(tn, CAUSAL) - count_phrases(anc_text, CAUSAL)))
    f["abs_new_anc"] = float(len(count_phrases(tn, ABSOLUTES) - count_phrases(anc_text, ABSOLUTES)))

    if best is not None and best < len(fuentes):
        g, gr, tl = span_gap(stems, fuentes[best])
    else:
        g = gr = tl = 0.0
    f["gap"] = g
    f["gap_ratio"] = gr
    f["tail"] = tl
    # cobertura: qué fracción de la fuente citada recoge la respuesta
    cs_seq = set(content_seq(fuentes[best])) if best is not None and best < len(fuentes) else set()
    f["cit_cover"] = len(stems & cs_seq) / max(1, len(cs_seq))

    h_src = count_phrases(rel_text, HEDGES)
    h_ans = count_phrases(tn, HEDGES)
    f["hedge_lost"] = float(len(h_src - h_ans))
    f["hedge_new"] = float(len(h_ans - h_src))
    a_ans = count_phrases(tn, ABSOLUTES)
    f["abs_new"] = float(len(a_ans - count_phrases(rel_text, ABSOLUTES)))
    f["abs_new_all"] = float(len(a_ans - count_phrases(all_text, ABSOLUTES)))
    c_ans = count_phrases(tn, CAUSAL)
    f["causal_new"] = float(len(c_ans - count_phrases(rel_text, CAUSAL)))
    f["causal_new_all"] = float(len(c_ans - count_phrases(all_text, CAUSAL)))
    f["n_rel"] = float(len(rel))
    f["n_src"] = float(n_src)
    f["len_words"] = math.log1p(len(texto.split()))
    return f


def case_context(caso):
    fuentes = caso["fuentes"]
    src_norm = [norm(s) for s in fuentes]
    src_nums = [set(v for v in extract_numbers(s) if not is_trivial(v)) for s in fuentes]
    allnums = set().union(*src_nums) if src_nums else set()
    src_caps = [caps(s) for s in fuentes]
    # entidades presentes en casi todas las fuentes no distinguen nada
    from collections import Counter
    cnt = Counter(c for cs in src_caps for c in cs)
    common = {c for c, k in cnt.items() if k >= max(2, 0.6 * len(fuentes))}
    pregunta = caso.get("pregunta") or ""
    return {
        "src_norm": src_norm,
        "all_norm": " ".join(src_norm),
        "src_nums": src_nums,
        "nums": allnums,
        "q_nums": set(extract_numbers(pregunta)),
        "times": [t for s in fuentes for t in extract_times(s)],
        "pcts": set(v for s in fuentes for v in extract_pcts(s)),
        "derived": derived_values(allnums),
        "src_caps": src_caps,
        "common_caps": common,
        "q_caps": caps(pregunta),
        "src_stems": [content_stems(s) for s in fuentes],
        "all_stems": content_stems(" ".join(fuentes)),
        "q_stems": content_stems(pregunta),
    }


def case_sentence_features(caso):
    sen = caso.get("senales") or {}
    oraciones = sen.get("oraciones") or []
    frags = sen.get("fragmentos") or []
    ctx = case_context(caso)
    out = []
    for i, o in enumerate(oraciones):
        fr = [x for x in frags if x.get("oracion") == i]
        out.append(sentence_features(o, fr, caso, ctx))
    if not out:  # sin señales: tratamos la respuesta entera como una oración vacía
        out.append(sentence_features({"texto": caso.get("respuesta", "")}, [], caso, ctx))
    return out

